const sources = $('Webhook').first().json.body?.sources || [];
const parseObject = (value) => {
  if (value && typeof value === 'object') return value;
  if (typeof value !== 'string' || !value.trim()) return {};
  try { return JSON.parse(value); } catch { return {}; }
};
return $input.all().map((item, fallbackIndex) => {
  const row = item.json || {};
  const lmInput = parseObject(row.lm_input);
  const lmOutput = parseObject(row.lm_output);
  const rawIndex = row.source_index ?? lmInput.source_index ?? row.row_index ?? fallbackIndex;
  const sourceIndex = Number(rawIndex);
  const source = sources[sourceIndex] || {};
  return {
    json: {
      source,
      originalEmail: source.email || '',
      ...lmOutput,
      leadmagic_status: row.status || '',
      leadmagic_error: row.error_message || null,
      row_index: Number(row.row_index ?? sourceIndex),
      source_index: sourceIndex,
      lm_input: lmInput,
      lm_output: lmOutput,
    },
  };
});

const request = $('When Executed by Another Workflow').first().json || {};
const sources = request.sources || request.rows || request.directRows || [];
const parseObject = (value) => {
  if (value && typeof value === 'object') return value;
  if (typeof value !== 'string' || !value.trim()) return {};
  try { return JSON.parse(value); } catch { return {}; }
};
const clean = (value) => String(value ?? '').trim();
const lower = (value) => clean(value).toLowerCase();
const host = (value) => {
  let x = lower(value);
  if (x.startsWith('https://')) x = x.slice(8);
  else if (x.startsWith('http://')) x = x.slice(7);
  if (x.startsWith('www.')) x = x.slice(4);
  return x.split('/')[0];
};
const identityKey = (value = {}) => [
  lower(value.firstName || value.first_name),
  lower(value.lastName || value.last_name),
  host(value.domain || value.company_domain || value.website)
].join('|');
const byEmail = new Map();
const byIdentity = new Map();
sources.forEach((source, index) => {
  const email = lower(source.email);
  if (email) byEmail.set(email, { source, index });
  const key = identityKey(source);
  if (key !== '||') byIdentity.set(key, { source, index });
});
const resolveSource = (row, lmInput, fallbackIndex) => {
  const raw = row.source_index ?? lmInput.source_index ?? row.row_index;
  const numeric = Number(raw);
  const candidates = [numeric, numeric - 1, fallbackIndex].filter(Number.isInteger);
  for (const index of candidates) {
    if (index >= 0 && sources[index]) return { source: sources[index], index };
  }
  const inputEmail = lower(
    row.original_email || row.input_email || lmInput.originalEmail ||
    lmInput.original_email || lmInput.email
  );
  if (inputEmail && byEmail.has(inputEmail)) return byEmail.get(inputEmail);
  const key = identityKey({
    firstName: row.first_name || lmInput.firstName || lmInput.first_name,
    lastName: row.last_name || lmInput.lastName || lmInput.last_name,
    domain: row.domain || row.company_domain || lmInput.domain || lmInput.company_domain,
  });
  if (key !== '||' && byIdentity.has(key)) return byIdentity.get(key);
  return { source: {}, index: Number.isInteger(numeric) ? numeric : fallbackIndex };
};
const results = $input.all().map((item, fallbackIndex) => {
  const row = item.json || {};
  const lmInput = parseObject(row.lm_input);
  const lmOutput = parseObject(row.lm_output);
  const resolved = resolveSource(row, lmInput, fallbackIndex);
  const source = resolved.source || {};
  const email = clean(row.email_finder_email || lmOutput.email);
  const providerStatus = clean(
    row.email_finder_validation_status || row.email_finder_status_2 ||
    row.email_finder_status1 || lmOutput.status
  );
  return {
    ...lmOutput,
    source,
    sourceKey: identityKey(source),
    originalEmail: clean(source.email),
    email,
    provider: 'LeadMagic',
    status: email ? 'Good' : 'Bad',
    detail: clean(
      row.email_finder_message || lmOutput.message || row.error_message ||
      (email ? providerStatus || 'valid' : 'not_found')
    ),
    leadmagic_status: clean(row.email_finder_status || row.status),
    leadmagic_error: row.error_message || null,
    row_index: Number(row.row_index ?? resolved.index),
    source_index: resolved.index,
  };
});
const { rows, sources: omittedSources, directRows, ...meta } = request;
const leadmagicJob = $('HTTP Request2').first().json || {};
return [{ json: {
  ...meta,
  results,
  leadmagicJobId: leadmagicJob.jobId || '',
  leadmagicJobName: request.jobName || ''
} }];
